UPDATE public.questions SET stimulus = $hdsat_report_fix$In medieval European scriptoria, parchment made from calfskin (vellum) was prized for illuminated manuscripts because its smooth, low-lipid surface accepted gold leaf and mineral pigments evenly. However, archival multispectral imaging of twelfth-century parish registries—documents intended for routine administrative tracking rather than liturgical display—shows that scribes overwhelmingly selected coarser sheepskin parchment, which split easily if scraped to remove ink, ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"because registries were administrative, scribes chose sheepskin's tamper resistance and lower cost."},{"id":"B","text":"Multispectral imaging cannot distinguish between calfskin and sheepskin in illuminated liturgical manuscripts."},{"id":"C","text":"Twelfth-century scribes lacked access to mineral pigments when compiling administrative parish registries."},{"id":"D","text":"Vellum manuscripts deteriorated more rapidly in parish archives than sheepskin registries did."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-INF-002$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The passage contrasts vellum (prized for decorative illumination) with sheepskin (used for administrative registries and prone to splitting if someone tried to scrape off ink). The correct completion explains why administrative use favoured the coarser, harder-to-erase sheepskin.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage notes registries were not intended for liturgical display, not that pigments were unavailable.","D":"Durability over centuries is not compared in the passage.","B":"Multispectral imaging was successfully used to identify the parchment type."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-INF-002$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Agronomists tested four cover-crop mixtures across 120 days to evaluate soil nitrogen retention and late-season weed suppression in upper Midwest plots. The researchers concluded that pairing a legume with a cereal grass allows farmers to capture nearly the full weed-suppression benefit of the grass without sacrificing the high nitrogen retention of the legume.$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most effectively uses data from the table to support the researchers' conclusion?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The Clover + Rye mix reached 86% suppression and retained 64 kg/ha, close to both single-crop benchmarks."},{"id":"B","text":"Tillage Radish retained 51 kg/ha and suppressed 72% of weeds, outperforming Winter Rye in nitrogen retention."},{"id":"C","text":"Crimson Clover retained 68 kg/ha, the highest nitrogen retention among all four treatments in the trial."},{"id":"D","text":"Winter Rye alone suppressed 89% of weeds, whereas Crimson Clover alone suppressed only 54% of weeds."}]$hdsat_report_fix$::jsonb, figure_metadata = $hdsat_report_fix${"type":"table","caption":"120-Day Cover Crop Trial Results","headers":["Cover Crop Treatment","Soil Nitrogen Retained (kg/ha)","Weed Suppression (%)"],"rows":[["Crimson Clover (legume)","68","54%"],["Winter Rye (cereal grass)","42","89%"],["Clover + Winter Rye (50/50)","64","86%"],["Tillage Radish (brassica)","51","72%"]]}$hdsat_report_fix$::jsonb, skill = $hdsat_report_fix$Command of Evidence (Quantitative)$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-INF-003$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The 50/50 mix reaches 86% weed suppression, close to Winter Rye's 89%, and retains 64 kg/ha, close to Crimson Clover's 68 kg/ha. It therefore keeps most of both single-crop benefits; the other choices cite only one crop or an irrelevant treatment.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Tillage Radish is neither the legume nor the cereal grass in the conclusion.","C":"Cites only Crimson Clover's nitrogen retention.","D":"Mentions only the single-crop extremes without citing the paired mixture."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-INF-003$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Paleoclimatologists reconstructing monsoon intensity from stalagmite oxygen-isotope ratios ($\delta^{18}\text{O}$) long assumed that lower $\delta^{18}\text{O}$ values in cave calcite strictly reflect higher local rainfall volume. Recently, however, atmospheric tracer models demonstrated that shifts in the geographic moisture source—from the Arabian Sea to the Bay of Bengal—can lower precipitation $\delta^{18}\text{O}$ by up to 3 per mil even when total local rainfall remains constant.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Oxygen-isotope ratios in cave calcite remain constant regardless of changes in regional monsoon circulation."},{"id":"B","text":"Stalagmites formed near the Arabian Sea grow more rapidly than those formed near the Bay of Bengal."},{"id":"C","text":"Atmospheric tracer models are less reliable than stalagmite calcite measurements for dating ancient cave formations."},{"id":"D","text":"Interpreting stalagmite $\\delta^{18}\\text{O}$ records as a direct measure of local rainfall volume may be inaccurate if concurrent changes in moisture-source pathways are not accounted for."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-INF-006$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Because changes in the geographic moisture source can alter $\delta^{18}\text{O}$ by up to 3 per mil without any change in local rainfall volume, attributing lower $\delta^{18}\text{O}$ solely to local rainfall volume can be misleading unless source-pathway changes are considered.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Stalagmite growth rate is not discussed.","A":"Contradicts the text, which explains two different factors that change $\\delta^{18}\\text{O}$.","C":"Radiometric dating of caves is not the subject of the passage."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-INF-006$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Text 1
Urban ecologist Marcus Vance contends that planting non-native drought-tolerant street trees in arid cities is an ecological mistake. Because native insect herbivores have not co-evolved with exotic foliage, non-native canopies support up to 70% fewer caterpillar species, depriving migratory songbirds of essential protein during spring stopovers.

Text 2
Landscape hydrologist Elena Rostova notes that in heavily paved metropolitan heat islands, soil compaction and radiant heat create microclimates several degrees hotter and drier than the surrounding native desert. In her multi-year survey of Phoenix boulevards, several native riparian tree species suffered high canopy dieback, whereas selected non-native Mediterranean oaks maintained dense shade that cooled adjacent sidewalks by 6°C and allowed understory native shrubs to survive.$hdsat_report_fix$, prompt = $hdsat_report_fix$Based on the texts, how would Rostova (Text 2) most likely respond to Vance's argument (Text 1)?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"By disputing Vance's finding that migratory songbirds rely on caterpillars during spring stopovers."},{"id":"B","text":"By arguing that urban planners should replace all street trees with artificial shade structures to conserve water."},{"id":"C","text":"By agreeing that non-native Mediterranean oaks should be removed from arid cities immediately."},{"id":"D","text":"By pointing out that in extreme urban microclimates where native trees struggle to survive, resilient non-native trees can provide microclimate cooling that indirectly supports native understory plants."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Cross-Text Connections$hdsat_report_fix$, domain = $hdsat_report_fix$Craft and Structure$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-CRF-005$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Rostova shows that paved urban heat islands are harsher than surrounding deserts, causing some native trees to die back while hardy non-native trees provide shade that cools sidewalks and helps native understory shrubs survive.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Rostova does not address or dispute songbird diet.","B":"Artificial shade structures are never mentioned.","C":"Rostova highlights the benefits of Mediterranean oaks in Phoenix boulevards."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-CRF-005$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Before the 1890s, Paris hotels removed carpets seasonally and washed them in the Seine. After the municipal water scheme of 1893, most hotels installed steam laundries that used half the water per rug, and the riverside carpet-washing wharves disappeared within a decade.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Steam laundries used more water per rug than the Seine wharves had."},{"id":"B","text":"The wharves were closed by ordinance following complaints about river pollution."},{"id":"C","text":"In-house steam laundries made riverside carpet washing economically obsolete."},{"id":"D","text":"Hotel operators could no longer transport carpets to the river after 1893."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-INF-301$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The passage contrasts the old river method with cheaper in-house washing that used half the water; the natural completion is that the new technology eliminated the old one on cost.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage states the steam laundries used half the water, not more.","B":"No ordinance or pollution complaint is mentioned.","D":"Nothing suggests transport difficulty; the wharves became unnecessary."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-INF-301$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Text 1
Agronomist Isabel Ferro maintains that no-till farms build soil carbon fastest when residue from the previous grain crop is left standing; the stalks act as miniature snow fences that raise winter soil moisture.
Text 2
Soil chemist Nowsherwan Ali counters that on the clay-heavy fields he studies, standing residue keeps the surface so wet and cold each spring that nitrogen mineralization begins two weeks late, costing more yield than the added moisture is worth.$hdsat_report_fix$, prompt = $hdsat_report_fix$Based on the texts, how would Ali most likely respond to Ferro?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"He would point out that Ferro's farms are too small to matter statistically."},{"id":"B","text":"He would agree that standing residue raises winter moisture but argue that on wet clay soils that same moisture delays spring nitrogen release and lowers yields."},{"id":"C","text":"He would dispute that residue affects soil moisture at all, since his fields are clay."},{"id":"D","text":"He would insist that residue be chopped and incorporated regardless of results."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Cross-Text Connections$hdsat_report_fix$, domain = $hdsat_report_fix$Craft and Structure$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-INF-304$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Ali accepts the moisture mechanism (that is Ferro's own point) and flips it: on his soils, the same moisture is a cost. The keyed choice captures agreement-plus-reversal.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"He does not deny moisture effects; he disagrees about their value on clay.","D":"He never proposes chopping residue; he weighs trade-offs.","A":"He critiques the agronomic trade-off, not study size."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-INF-304$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Text 1
Nocturnist Omar Haddad writes that fall-prevention rounds at midnight are missing the point: most falls happen at 5-6 a.m., so the fix is protecting the 5:30 medication walk, not adding midnight checks.
Text 2
Orthopedic data analyst Jena Fox replies that in her system's log, falls cluster at the midnight-to-2 a.m. shift handover, when two different teams each assume the other has done hourly rounds.$hdsat_report_fix$, prompt = $hdsat_report_fix$Based on the texts, how would Fox most likely respond to Haddad?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"By disputing that medication walks occur at 5:30 a.m. at all."},{"id":"B","text":"By citing her handover-hour data to argue that midnight checks would catch the falls Haddad's own timing analysis might miss."},{"id":"C","text":"By agreeing that both 5:30 and midnight rounds are worthless investments."},{"id":"D","text":"By proposing that fall prevention shifts entirely to the morning shift."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Cross-Text Connections$hdsat_report_fix$, domain = $hdsat_report_fix$Craft and Structure$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-INF-319$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Her data locates risk elsewhere (handover), so she would push back with that timing evidence rather than accept Haddad's window.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"She would not dismiss both windows; she would add hers.","A":"She does not dispute that walks happen.","D":"Her point is about handover, not mornings generally."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-INF-319$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Text 1
In a study of prescribed low-intensity woodland burns, ecologist Mara Vance argues that spring burns maximize understory wildflower diversity. According to ecologist Mara Vance, expanding this practice across comparable sites would yield immediate, measurable gains.

Text 2
Evaluating the same prescribed low-intensity woodland burns, forester Jian Zhou observes that autumn burns better protect nesting canopy birds while still clearing dry fuel. Consequently, forester Jian Zhou cautions against adopting the practice without targeted safeguards.$hdsat_report_fix$, prompt = $hdsat_report_fix$Based on the texts, how would forester Jian Zhou most likely respond to ecologist Mara Vance's view of prescribed low-intensity woodland burns?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"By arguing that prescribed low-intensity woodland burns should be abandoned immediately in all circumstances."},{"id":"B","text":"By acknowledging the potential benefit of prescribed low-intensity woodland burns while pointing out an unintended consequence that requires design or timing adjustments."},{"id":"C","text":"By claiming that ecologist Mara Vance's measurements were fabricated without field testing."},{"id":"D","text":"By agreeing that prescribed low-intensity woodland burns produces no measurable side effects whatsoever."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Cross-Text Connections$hdsat_report_fix$, domain = $hdsat_report_fix$Craft and Structure$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-CRF-88401$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Text 1 highlights how spring burns maximize understory wildflower diversity, whereas Text 2 notes that autumn burns better protect nesting canopy birds while still clearing dry fuel. 'By acknowledging the potential benefit of prescribed low-intensity woodland burns while pointing out an unintended consequence that requires design or timing adjustments.' accurately synthesizes how the two perspectives relate.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"“By arguing that prescribed low-intensity woodland burns should be abandoned immediately in all circumstances.” overstates or misstates the disagreement between the two authors.","C":"“By claiming that ecologist Mara Vance's measurements were fabricated without field testing.” overstates or misstates the disagreement between the two authors.","D":"“By agreeing that prescribed low-intensity woodland burns produces no measurable side effects whatsoever.” overstates or misstates the disagreement between the two authors."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-CRF-88401$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Text 1
