UPDATE public.questions SET stimulus = $hdsat_report_fix$A Roman water wheel recovered from a riverbed had wooden paddles worn thin on one face only. The wear pattern matches contact with flowing water rather than with sand or gravel. The wheel's axle showed no sign of having been turned by an animal. Together these details suggest that the wheel was driven by the current itself.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The wear on the paddles came from abrasive gravel in the riverbed."},{"id":"B","text":"The wheel was turned by oxen walking on a circular track."},{"id":"C","text":"The wheel was never used and was abandoned before installation."},{"id":"D","text":"The wheel was a water-powered device rather than one turned by animals or people."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0152$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The evidence points to current-driven rotation and away from animal power or abrasion.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"The axle shows no animal-drive wear.","A":"The wear matches flowing water, not sand or gravel.","C":"Use is implied by the wear pattern."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0152$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Bats emit calls at frequencies too high for most people to hear. A detector that records ultrasound can therefore reveal species that mist-netting misses, because nets catch only animals flying at net height. In one survey, detectors registered eight species at a site where nets had caught three. The two methods were not measuring the same thing.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The survey proved that only three species live at the site."},{"id":"B","text":"Acoustic detectors capture bats physically for identification."},{"id":"C","text":"Combining acoustic detectors with nets gives a fuller species list than either method alone."},{"id":"D","text":"Mist-netting is more reliable than acoustic detection for every species."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0153$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Each method samples differently, so the union is more complete than either alone.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Nets missed five species the detectors found.","B":"Detectors record sound; nets catch animals.","A":"The detectors found eight species, so three is incomplete."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0153$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Legumes host bacteria in root nodules that convert atmospheric nitrogen into a form plants can use. A field planted with legumes for one season contains more available nitrogen the following year, even after the plants are harvested. Farmers who rotate legumes with cereals often reduce their fertiliser use without lowering yields.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The nitrogen remains in the soil and benefits the next crop."},{"id":"B","text":"Root-nodule bacteria convert nitrogen into a gas that plants cannot use."},{"id":"C","text":"Cereal yields fall whenever legumes are grown in rotation."},{"id":"D","text":"Legumes remove nitrogen from the soil and deplete it for later crops."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0154$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The rotation effect follows from fixed nitrogen remaining available to the following crop.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"The passage says available nitrogen increases.","C":"Yields are maintained while fertiliser falls.","B":"The bacteria produce a usable form."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0154$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Lighthouse keepers recorded weather every few hours for over a century. Their logs note wind direction, cloud cover and the first appearance of ice. Historians comparing these entries with ships' logs from the same waters find close agreement on storms but frequent disagreement on calm days. The keepers' records are therefore most valuable for severe weather.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The keepers' logs should be discarded because they disagree with ships' logs."},{"id":"B","text":"Ships' logs are unreliable because they were written at sea."},{"id":"C","text":"The logs are most trustworthy where independent records confirm them, especially during storms."},{"id":"D","text":"Calm days are the best evidence of the keepers' accuracy."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0155$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Agreement during storms supports using the logs for severe weather, not for calm conditions.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Agreement on storms makes the logs useful there.","D":"Disagreement is most frequent on calm days.","B":"The passage does not accuse ships' logs of unreliability."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0155$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Paper marbling floats pigments on a thickened bath, then lays paper on the surface to lift the pattern. Because the bath is viscous, the colors move slowly and can be combed before printing. Two sheets made minutes apart from the same bath differ, since each lift removes pigment. No two marbled sheets are identical.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The combing step prevents any pattern from forming."},{"id":"B","text":"Each print is unique because lifting the paper removes pigment from the bath."},{"id":"C","text":"Marbled sheets are identical because the bath is stirred between prints."},{"id":"D","text":"Pigments sink immediately in the thickened bath."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0156$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Depletion of pigment at each lift explains the uniqueness of every sheet.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage says each lift removes pigment and changes the pattern.","D":"The viscous bath slows movement rather than sinking.","A":"Combing shapes the pattern before printing."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0156$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A lake core contains a thin, pale layer of volcanic ash between darker organic sediment. The ash layer is the same thickness at both ends of the lake, which is unusual for sediment that normally thins away from shore. Geologists conclude that the ash fell directly onto the lake surface across its whole extent in a very short interval.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The layer records a single airborne deposit rather than material washed in from the shore."},{"id":"B","text":"The lake was dry when the ash fell."},{"id":"C","text":"The layer was deposited by a river entering the lake."},{"id":"D","text":"The ash drifted in slowly from one shoreline over many years."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0157$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Uniform thickness across the basin points to airborne deposition over a short time.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"A direct fall explains uniform thickness across the lake.","C":"River input would thin away from the inlet.","B":"A dry lake would not preserve an even layer in sediment."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0157$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Nest temperature determines the sex of some turtle hatchlings. On beaches where shade from vegetation has increased, nests stay cooler and produce more males. Conservationists who move nests to open sand to protect them from tides may unintentionally raise temperatures. Protection and sex ratio can therefore pull in opposite directions.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Moving nests to open sand guarantees a balanced sex ratio."},{"id":"B","text":"Shade has no effect on hatchling sex."},{"id":"C","text":"Tides are the only threat to nests on shaded beaches."},{"id":"D","text":"A nest-relocation program should consider temperature as well as protection from tides."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0158$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The two goals conflict, so relocation must account for both.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Open sand is warmer, which skews the ratio.","B":"The passage says temperature determines sex.","C":"The text mentions vegetation and temperature, not only tides."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0158$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Iron-gall ink etches paper as it ages because it releases acid. A manuscript written in the fifteenth century may have holes where the ink was thickest, even though the surrounding paper is sound. Conservators treat such leaves cautiously: washing removes acid but can also loosen the remaining ink, so a treatment that helps the paper may erase the text.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Preservation choices must balance saving the paper against losing the writing on it."},{"id":"B","text":"Holes appear where the ink was thinnest."},{"id":"C","text":"Washing always restores both the paper and the ink."},{"id":"D","text":"Iron-gall ink strengthens paper where it is applied."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0159$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The risk of losing ink sets a limit on acid removal.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"Washing can loosen the ink.","D":"The ink releases acid and etches the paper.","B":"Holes appear where the ink was thickest."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0159$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Tree rings are wide in years with abundant moisture and narrow in dry years. A stand of oaks on a dry ridge shows narrow rings in the same years as a stand in a wet valley nearby. Because both stands respond to the same regional rainfall, the shared pattern lets researchers cross-date the two records and build one longer chronology.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The two stands grew at different rates and cannot be compared."},{"id":"B","text":"Wide rings indicate drought at both sites."},{"id":"C","text":"A climate signal common to both sites allows their rings to be aligned in time."},{"id":"D","text":"Cross-dating depends on counting rings from the outside inward."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0160$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$A shared rainfall signal produces matching narrow years that align the chronologies.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The shared narrow years make alignment possible.","B":"Wide rings indicate moisture, not drought.","D":"The passage explains alignment by shared climate, not by a counting direction."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0160$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A foraging bee that finds a rich patch returns to the hive and performs a figure-eight dance. The angle of the dance's straight run relative to vertical corresponds to the direction of the food relative to the sun. When researchers rotated the hive, the dancers adjusted the angle, and the other bees still found the patch.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The dance encodes direction in a way that stays accurate as the hive's orientation changes."},{"id":"B","text":"Rotating the hive made the other bees unable to find the patch."},{"id":"C","text":"The dance communicates only the distance to food, not its direction."},{"id":"D","text":"The angle of the dance is fixed and unrelated to the sun."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0161$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Adjustment after rotation shows the angle carries usable directional information.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The angle corresponds to direction.","B":"The bees still found the patch after rotation.","D":"The angle is measured relative to the sun."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0161$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Roman fish sauce was made by packing fish with salt and leaving the mixture in the sun for weeks. The salt drew water out of the tissue and suppressed the bacteria that would otherwise spoil it. Amphorae found on shipwrecks still contain residues of the sauce, and their sealed interiors kept the contents from exchanging with seawater.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The sauce survived because seawater flushed through the amphorae."},{"id":"B","text":"Salt encouraged the bacteria that spoil fish."},{"id":"C","text":"The residues found on shipwrecks are unrelated to fish sauce."},{"id":"D","text":"Salt preservation and sealed storage together kept the sauce chemically distinct for centuries."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0162$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Preservation plus sealing explains why residues survived intact.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Sealed interiors are said to have kept seawater out.","B":"Salt suppressed spoilage bacteria.","C":"The passage identifies the residues as the sauce."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0162$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Deep-sea corals grow in cold water and lack the algae that feed shallow reefs. They capture food from passing currents instead, and their skeletons grow slowly enough that a colony may be centuries old. Radiocarbon dating of a specimen showed that its base was far older than its living branches, so the colony is best understood as a long-lived structure rather than a single animal.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Deep-sea corals depend on algae for food."},{"id":"B","text":"The living branches are the oldest part of the colony."},{"id":"C","text":"The age of a coral colony is set by the whole structure, not only by its living tissue."},{"id":"D","text":"Cold-water corals grow faster than shallow-water corals."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0163$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Dating the base older than the branches shows the structure's age spans the whole colony.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"The passage says their skeletons grow slowly.","B":"The base is older than the living branches.","A":"They lack symbiotic algae and catch food from currents."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0163$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Readers of old books sometimes wrote in the margins. A note may correct a printer's error, argue with the author, or record the date a reader finished the volume. Because marginalia are attached to a specific copy, they can show how one book traveled between owners. Historians therefore treat them as evidence of reading practice rather than as damage to be removed.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"All marginal notes record the same kind of information."},{"id":"B","text":"The value of marginalia lies in what they reveal about the people."},{"id":"C","text":"Removing marginalia improves the historical record."},{"id":"D","text":"Marginalia are valuable mainly because they restore the printed text."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0164$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The notes attach evidence of reading and ownership to a specific copy.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Their value is evidence of use, not restoration.","A":"The passage lists several different kinds of note.","C":"Historians treat the notes as evidence, not damage."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0164$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A retreating glacier leaves a valley with steep sides and a flat floor. A river valley of similar size usually has a V-shaped cross-section, because running water cuts downward and inward. The U-shape of a glaciated valley therefore records that ice, which erodes sideways as well as downward, once filled the space.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The shape of a valley can indicate whether ice or a river formed it."},{"id":"B","text":"Valley shape is unrelated to the agent of erosion."},{"id":"C","text":"A retreating glacier leaves a deep V-shaped trench."},{"id":"D","text":"Rivers carve U-shaped valleys more often than glaciers do."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0165$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The contrast between U- and V-shaped profiles is the evidence for the erosional agent.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"The text attributes U-shapes to ice and V-shapes to rivers.","C":"Glacial valleys are described as U-shaped.","B":"The passage draws the conclusion from shape."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0165$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Coffee grown under shade trees ripens more slowly than coffee grown in full sun. The slower ripening produces denser beans, and tasters often describe the cup as more complex. Yields per hectare, however, are lower under shade, and farmers must weigh the price premium against the reduced volume harvested.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Shade - grown coffee can earn more per bean."},{"id":"B","text":"Shade trees raise yields without affecting quality."},{"id":"C","text":"Shade-grown coffee always earns more per hectare than sun-grown coffee."},{"id":"D","text":"Full-sun coffee produces denser beans than shade-grown coffee."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0166$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Quality and price rise while volume falls, creating a trade-off.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage says yields are lower, so per-hectare earnings are not guaranteed.","D":"Slower ripening under shade produces denser beans.","B":"The text says shade lowers yields."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0166$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Honey often contains pollen grains from the flowers the bees visited. Because pollen grains have distinctive shapes, a sample can reveal which plants were in bloom. Analysis of a jar from a market stall showed pollen from a plant that flowers only in early spring, several months before the honey was sold. The jar was probably not from the most recent harvest.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Pollen analysis cannot distinguish one season's honey from another's."},{"id":"B","text":"Bees visit only one plant species in a season."},{"id":"C","text":"The jar was certainly made from artificial honey."},{"id":"D","text":"Pollen can date honey by showing which flowering season produced it."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0167$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Season-specific pollen in a jar sold later points to an earlier harvest.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Distinctive pollen tied to a season is exactly what enables dating.","C":"The passage infers age, not adulteration.","B":"The passage describes pollen from visited flowers generally."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0167$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Shipworms bore into wooden hulls and pilings, digesting the wood with the help of bacteria. A hull recovered from a cold, low-oxygen harbour showed far less damage than one from a warm estuary. Conservators now store excavated timbers in tanks where oxygen is limited, because the animals that attack wood need oxygen as well as wood.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Warm water protects wood from shipworms."},{"id":"B","text":"Oxygen has no effect on wood-boring animals."},{"id":"C","text":"Limiting oxygen slows the organisms that would otherwise consume waterlogged wood."},{"id":"D","text":"Shipworms digest wood without the help of bacteria."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0168$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The comparison and the storage practice both turn on oxygen.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The warm estuary showed more damage.","D":"The passage mentions bacterial help.","B":"The storage method relies on oxygen limitation."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0168$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A solar still collects drinking water by evaporating brine under a transparent cover and condensing the vapour on the underside. Output depends on sunlight and on the area of the cover. On a cloudy day a small still may produce only a few spoonfuls, while a larger still in full sun produces liters. The device is therefore a supplement rather than a stand-alone supply.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Condensation reduces the amount of water collected."},{"id":"B","text":"A solar still's output is too weather-dependent to guarantee water on its own."},{"id":"C","text":"A solar still produces the same output in all weather."},{"id":"D","text":"Small stills outperform large ones in full sun."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0169$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Variable output under clouds explains why the device is a supplement.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage describes output varying with sunlight and area.","D":"Larger stills in full sun produce liters.","A":"Condensation is the collection step."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0169$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Fish ferment faster in warm weather, and salt slows the process. Communities that live where temperatures stay high use more salt in their preserved fish than communities in cooler regions. A recipe that works in one place can therefore fail in another, not because the method is wrong but because the conditions have changed.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Preservation recipes have to be adjusted to local temperature."},{"id":"B","text":"Salt speeds fermentation in warm weather."},{"id":"C","text":"Cooler regions require more salt than warmer ones."},{"id":"D","text":"A recipe that works in one region always works in another."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0170$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Temperature changes the rate of fermentation, so salt amounts must adapt.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Salt slows fermentation.","C":"The passage says warmer communities use more salt.","D":"The passage says a recipe can fail when conditions change."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0170$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A cathedral bell is tuned by grinding metal from its rim. Removing material lowers the pitch and can also change the relationships among the bell's partial tones. Founders therefore remove metal in small stages, testing between each. A bell ground too far cannot be restored, because the metal cannot be added back.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Tuning is irreversible, so it proceeds cautiously and in measured steps."},{"id":"B","text":"Grinding raises the pitch of a bell."},{"id":"C","text":"Partial tones are unaffected by removing metal."},{"id":"D","text":"Founders grind the rim quickly because extra metal can be added later."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0171$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Irreversibility explains the incremental method. The keyed choice follows from the passage's stated relationship, while the other options either contradict it or go beyond what the text supports.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Metal cannot be added back.","B":"The passage says removing material lowers pitch.","C":"Grinding can change the partial relationships."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0171$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Compacted soil resists root growth even when it holds enough water. Roots follow pores and cracks, and compaction closes those channels. In a field where machinery has passed repeatedly, roots may spread sideways above a hard layer instead of reaching deeper moisture. The plants survive but depend on rain in the upper soil.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Compaction makes crops more vulnerable to drought in the upper soil."},{"id":"B","text":"Roots grow through compacted soil more easily than through pores."},{"id":"C","text":"Machinery traffic improves the soil's pore structure."},{"id":"D","text":"Compaction helps roots reach deeper water."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0172$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The passage links shallow roots to reliance on upper-soil moisture, so drought there is the logical risk.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Roots are blocked from deeper layers.","B":"Roots follow pores, which compaction closes.","C":"Traffic is the cause of the compaction described."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0172$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Soot deposits on cave ceilings accumulate in thin layers that record the fires below. A layer rich in charcoal indicates a larger or more frequent fire; a gap indicates a period without burning. Archaeologists reading a sequence of layers can therefore reconstruct how often people used a cave, even when no tools survive.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Soot layers form only when a cave is empty of people."},{"id":"B","text":"Soot layers provide a record of human activity independent of artefacts."},{"id":"C","text":"Charcoal-rich layers indicate cold weather rather than fires."},{"id":"D","text":"A gap in the layers proves that the cave was never visited."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0173$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The layers record burning even when no tools survive, which is why they can establish occupation independently.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage says the layers record use.","D":"A gap indicates a period without burning, not no visits.","C":"Charcoal richness tracks fire size or frequency."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0173$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Harbour sediment traps lead, copper and organic matter washed from streets and ships. A core taken near a former shipyard contains a sharp peak in copper at the depth corresponding to the yard's busiest decades. Above that layer, concentrations fall as the yard closed and runoff was diverted. The core therefore reads as a history of industrial activity.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Chemical layers in harbour mud can be tied to the rise and fall of nearby industry."},{"id":"B","text":"Copper concentrations rise after the shipyard closed."},{"id":"C","text":"Harbour sediment carries no trace of industrial activity."},{"id":"D","text":"The peak in copper came from natural erosion only."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0174$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The copper peak aligns with the shipyard's busiest years, so the sediment layers track the industry's rise and fall.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Concentrations fall above the peak as the yard closed.","C":"The passage describes clear traces.","D":"The peak corresponds to the yard's busiest decades."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0174$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Bats that hibernate through winter need high humidity as well as steady cold. Dry air draws water from their skin and wings, and an aroused bat burns fat it cannot replace until spring. A cave that is cold but draughty can therefore be worse for a colony than one that is slightly warmer but still.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Bats can replace fat easily during winter."},{"id":"B","text":"Air movement has no effect on hibernating bats."},{"id":"C","text":"Stable, humid conditions matter more to hibernating bats than cold alone."},{"id":"D","text":"Warm, dry caves are ideal for hibernating bats."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0175$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Humidity and stillness protect the fat reserve that must last the winter.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Dry air causes water loss and arousal.","A":"The passage says fat cannot be replaced until spring.","B":"Draughty caves are described as harmful."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0175$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Roof tiles are laid so that each row overlaps the one below. Water running down the slope crosses from one tile to the next without reaching the deck beneath. If the overlap is too small, wind-driven rain can be forced upward under the edge. The overlap is therefore a specification, not a decorative choice.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Overlap width must be set to withstand the weather."},{"id":"B","text":"The overlap has no effect on whether rain reaches the deck."},{"id":"C","text":"Water runs upward across the roof under normal conditions."},{"id":"D","text":"A smaller overlap gives better protection in strong wind."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0176$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Because wind-driven rain can enter under a small overlap, the overlap must be sized for the weather the roof will face.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Too small an overlap lets wind-driven rain under the edge.","C":"Water runs down the slope; only driven rain moves upward.","B":"The overlap determines whether water crosses safely."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0176$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Some plants rely on ants to carry their seeds. The seed carries a fleshy appendage that ants eat, and the seed itself is discarded underground. Seeds moved this way end up buried, where they escape drying and some seed-eaters. The plant pays a small food cost for dispersal and burial.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Seeds left on the surface survive better than buried ones."},{"id":"B","text":"The food reward buys the seed both transport and a safer place to germinate."},{"id":"C","text":"Ants destroy the seeds they carry."},{"id":"D","text":"The appendage prevents ants from moving the seed."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0177$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Transport plus burial explains the benefit of the food cost.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The seed is discarded intact underground.","D":"The appendage is the reward that attracts ants.","A":"Burial is described as protection."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0177$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Clipper ships carried tea from China to London, and speed mattered because early arrivals sold at higher prices. Their hulls were narrow and their sail area large, which made them fast in strong winds but hard to handle in a calm. After steamships offered reliable schedules, the clippers lost their advantage.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Reliability of arrival proved more valuable than the fastest possible passage."},{"id":"B","text":"Clippers remained the fastest option after steamships appeared."},{"id":"C","text":"Speed had no effect on the price tea fetched."},{"id":"D","text":"Calm weather was the clippers' greatest advantage."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0178$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Steam's dependable schedule displaced the clipper's speed premium.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Clippers lost their advantage to steamships.","D":"The narrow hull was hard to handle in a calm.","C":"The passage says early arrivals sold higher."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0178$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Some birds lay eggs with thinner shells where the soil is low in calcium. The birds cannot manufacture calcium, so they must take it from food or grit. Studies of a population on calcium-poor ground found thinner shells and more breakages than in a population on limestone. The difference tracked geology, not species.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Birds can synthesise calcium without eating it."},{"id":"B","text":"Calcium-poor soil produces thicker shells."},{"id":"C","text":"Access to calcium in the environment shapes shell thickness in these birds."},{"id":"D","text":"Shell thickness is fixed by the species and cannot vary."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0179$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The geologic contrast, with the same species, isolates calcium availability.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"The two populations differ within the same species.","B":"Thin shells occur on poor ground.","A":"The passage says birds must obtain calcium from food or grit."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0179$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Residue inside Roman amphorae can be identified by its chemical signature. Jars found in a storage room contained traces of olive oil, while jars from a nearby shop contained fish sauce. The two sets were the same shape. Shape alone therefore does not tell an archaeologist what a vessel carried.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Fish sauce and olive oil leave identical residues."},{"id":"B","text":"Contents must be identified chemically, because form does not reveal use."},{"id":"C","text":"All jars in a storage room held the same product."},{"id":"D","text":"Amphora shape reliably indicates what was stored inside."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0180$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Same shape, different contents forces chemical identification. The keyed choice follows from the passage's stated relationship, while the other options either contradict it or go beyond what the text supports.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Identical shapes held different contents.","A":"The distinction comes from chemical signatures.","C":"The passage contrasts two nearby sets."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0180$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Pencil leads are graded by hardness, which depends on the ratio of graphite to clay. More clay makes a harder lead that holds a sharp point and prints lightly; more graphite makes a softer lead that darkens the page and wears quickly. A drafter choosing a lead is choosing between precision and darkness.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The graphite-to-clay ratio has no effect on wear."},{"id":"B","text":"Hard leads darken the page more than soft leads."},{"id":"C","text":"No single lead suits both fine detail and dense shading equally well."},{"id":"D","text":"Clay increases the darkness of a pencil line."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0181$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The trade-off between point retention and darkness is the basis of the grading scale.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Hard leads print lightly; soft leads darken.","D":"Graphite provides darkness, not clay.","A":"The ratio determines both darkness and wear."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0181$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A bleached coral reef can recover if the algae that live inside the coral return while the coral is still alive. Recovery is slower where the reef is also stressed by sediment or warm water. Surveys find that reefs with cleaner water regain color sooner after a bleaching event than reefs near river mouths.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Bleached coral is always dead and cannot recover."},{"id":"B","text":"Sediment speeds the return of algae to coral."},{"id":"C","text":"Warm water improves recovery after bleaching."},{"id":"D","text":"Reducing local stress helps a reef recover from bleaching."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0182$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The comparison points to local stress as a brake on recovery.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Cleaner-water reefs recovered sooner.","A":"The passage describes recovery while the coral is alive.","C":"Warm water is named as an additional stress."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0182$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Salmon that die after spawning leave carcasses in streams. Their bodies carry nitrogen from the ocean, which enters the food web as the carcasses decay. Trees along a stream with many spawning salmon contain more marine-derived nitrogen than trees along a stream without them. The forest is therefore linked to the ocean by the fish.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Marine nutrients reach streamside forests through the bodies of spawning fish."},{"id":"B","text":"Trees cannot take up nitrogen from decaying fish."},{"id":"C","text":"Salmon remove nitrogen from streamside forests."},{"id":"D","text":"The connection exists only in streams without spawning salmon."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0183$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The nitrogen signature in trees traces the marine source through the carcasses.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"The passage reports elevated nitrogen in those trees.","C":"The carcasses add nitrogen.","D":"The contrast is between streams with and without salmon."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0183$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A windmill's sails turn a shaft, and gearing converts that slow, powerful rotation into a faster one at the millstone. Changing the gear ratio changes the speed of the stone without changing the wind. Millers keep several gears on hand so that a strong wind and a light one can both be used.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Gearing lets a miller match the stone's speed to the available wind."},{"id":"B","text":"A single fixed gear ratio suits every wind condition."},{"id":"C","text":"The millstone turns more slowly than the shaft in all gears."},{"id":"D","text":"Gearing changes the amount of wind reaching the sails."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0184$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Multiple gears exist to keep stone speed steady across wind strengths.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Gearing converts rotation, not wind.","B":"The passage describes changing ratios for different winds.","C":"The gearing speeds the rotation up at the stone."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0184$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A manuscript written with acidic ink can lose text at the same time it loses paper. Washing a leaf removes acid but may also lift the ink, so conservators first test a small, unimportant area. If the ink survives the test, the leaf can be washed; if not, it is stored dry and digitised instead.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Every leaf can be washed safely with acidic ink."},{"id":"B","text":"Testing a small area damages the whole manuscript."},{"id":"C","text":"Digitisation removes acid from the paper."},{"id":"D","text":"Treatment decisions depend on evidence from a test before the whole leaf is exposed."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0185$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The small-area test governs whether the full treatment is safe.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Washing may lift the ink.","B":"The test uses an unimportant area precisely to avoid damage.","C":"Digitisation creates a copy; it does not treat the paper."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0185$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Moss on a stone wall is thickest on the side that receives the most moisture, not always the side that receives the most light. On a wall shaded by trees, moss may cover the whole face, while an exposed wall carries moss in a band near the ground. Anyone reading moss as a compass would need to know the local conditions.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Moss requires full sunlight and avoids damp surfaces."},{"id":"B","text":"Moss always grows on the north side of a wall regardless of shade."},{"id":"C","text":"A shaded wall carries less moss than an exposed one."},{"id":"D","text":"Moss growth reflects moisture and shade, so it is an unreliable direction indicator without local context."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0186$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Moisture and shade dominate, which defeats naive compass use.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"The passage says moisture matters more than direction.","A":"Moss is thickest where moisture is greatest.","C":"The shaded wall may be covered entirely."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0186$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Volcanic lightning occurs in ash clouds when particles collide and separate charge. The effect is more common in eruptions that produce fine ash and vigorous convection. Observers have used lightning detection to track eruptions at night and in bad weather, when cameras see little. The electrical signal becomes a remote sensing tool.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Volcanic lightning occurs only in eruptions with no ash."},{"id":"B","text":"Cameras see eruptions better at night than detectors do."},{"id":"C","text":"Lightning detection replaces the need to monitor volcanoes."},{"id":"D","text":"Detecting lightning can reveal an eruption that visibility would hide."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0187$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The electrical signal works when visual observation fails.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage ties lightning to fine ash and convection.","C":"It is a tool, not a replacement for monitoring.","B":"The text says cameras see little at night and in bad weather."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0187$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Wool takes dye unevenly if its scales are damaged. Makers therefore clean fleece gently and avoid sudden temperature changes during dyeing, since a rapid shift can shock the fibres. A dye lot that looks patchy often records a handling error rather than a fault in the dye itself.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Rapid temperature changes improve the evenness of dye uptake."},{"id":"B","text":"Damaged scales help wool absorb dye uniformly."},{"id":"C","text":"Even color depends on gentle handling as much as on the dye recipe."},{"id":"D","text":"Patchiness always indicates a faulty dye."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0188$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Handling errors, not the dye, explain many patchy lots.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage warns that rapid shifts shock the fibres.","B":"Damage is described as causing uneven uptake.","D":"Patchiness often reflects handling, not the dye."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0188$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Charcoal in lake sediment comes from fires in the surrounding catchment. A layer with abundant charcoal often coincides with a shift from forest pollen to grass pollen. The two signals together suggest that fire removed trees and allowed grasses to spread. Neither signal alone would establish the sequence.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Charcoal layers indicate that no fire occurred in the catchment."},{"id":"B","text":"Combining charcoal and pollen evidence links fire to vegetation change."},{"id":"C","text":"Pollen shifts always precede fires by several centuries."},{"id":"D","text":"Grass pollen excludes the possibility of fire."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0189$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The coincidence of the two proxies is what ties fire to the vegetation shift.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Charcoal records fire.","C":"The signals are described as coinciding.","D":"Grass pollen follows fire in the proposed sequence."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0189$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A tea clipper's narrow hull reduced drag but also reduced cargo space. Owners packed light, high-value cargo such as tea and raced for the first market. When the Suez Canal opened, steamships could take a shorter route that sailing ships could not use reliably. The clippers' advantage narrowed.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Narrow hulls increased cargo capacity."},{"id":"B","text":"A route change reduced the value of the clippers' speed and small capacity."},{"id":"C","text":"Clippers carried bulk cargo more cheaply after the canal opened."},{"id":"D","text":"The Suez Canal made the clippers' route shorter than the steamships'."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0190$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The canal favored steam, eroding the clipper's niche.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Steamships took the shorter route the clippers could not use.","C":"Clippers carried light, high-value cargo.","A":"The passage says the narrow hull reduced capacity."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0190$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A bell foundry casts a bell slightly larger than its final size because tuning removes metal. The founder also adjusts the profile so that the bell's partial tones form the intended chord. Changing the profile after casting is nearly impossible, so the shape must be right before the metal cools.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Tuning adds metal to raise the pitch."},{"id":"B","text":"The partial tones are unrelated to the bell's shape."},{"id":"C","text":"A bell's profile can be reshaped easily after casting."},{"id":"D","text":"Most of a bell's tonal character is fixed at casting, with tuning only refining it."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0191$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Since profile cannot be changed later, the cast shape carries the tonal design.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage says reshaping after casting is nearly impossible.","A":"Tuning removes metal.","B":"The profile is adjusted to shape the partials."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0191$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$An oyster reef filters water as its inhabitants feed. A dense reef can clear suspended particles from a large volume in a day. When reefs were removed, water clarity fell and sunlight reached less deeply. Seagrasses, which need light, declined in the same estuaries.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Water clarity improved after reefs were removed."},{"id":"B","text":"Oyster reefs increase suspended particles in the water."},{"id":"C","text":"Losing oyster reefs can reduce water clarity enough to harm seagrass."},{"id":"D","text":"Seagrasses grow better in turbid water."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0192$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Filtration loss, lower clarity and seagrass decline form the causal chain.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"The reef filters particles out.","D":"Seagrass needs light, which turbidity blocks.","A":"The passage says clarity fell."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0192$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A mudbrick wall shrinks as it dries. If the outer surface dries faster than the core, the difference in shrinkage pulls the surface apart. Builders therefore mix straw into the clay, which slows drying and gives the shrinking mass something to hold onto. The cracks that appear in unstrawed brick begin at the surface.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Mudbrick does not change size as it dries."},{"id":"B","text":"Straw reduces cracking by evening out the drying of a mudbrick."},{"id":"C","text":"Straw speeds drying and increases surface shrinkage."},{"id":"D","text":"Cracks in unstrawed brick start at the core."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0193$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Straw moderates the moisture gradient that causes surface cracking.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage says straw slows drying.","A":"The wall shrinks as it dries.","D":"The text says cracks begin at the surface."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0193$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Goats browse young trees before they can grow above reach. On islands where goats were removed, tree lines moved upslope within decades. On islands where goats remained, the same species stayed low and sparse. The difference between the islands tracks the presence of goats rather than climate.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Goats help young trees grow above browsing height."},{"id":"B","text":"Removing goats prevented trees from spreading."},{"id":"C","text":"Grazing animals can hold a tree line in place."},{"id":"D","text":"Tree lines are determined entirely by temperature."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0194$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The island comparison isolates grazing as the cause.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"The paired islands share climate but differ in goats.","B":"Tree lines moved upslope after removal.","A":"Goats browse young trees before they escape reach."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0194$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Lichens absorb water and nutrients directly through their surfaces, which also means they absorb pollutants. A lichen transplanted from a clean site to a city center accumulates metals within months. Species differ in tolerance, so a survey of which lichens survive can map pollution without instruments.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Lichens filter out pollutants and remain unaffected."},{"id":"B","text":"Lichen communities can act as biological pollution monitors."},{"id":"C","text":"All lichen species respond to pollution in the same way."},{"id":"D","text":"Transplanted lichens cannot accumulate metals."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0195$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Absorption plus species-specific tolerance supports biomonitoring. The keyed choice follows from the passage's stated relationship, while the other options either contradict it or go beyond what the text supports.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage says they absorb pollutants.","C":"Tolerance differs by species.","D":"The transplant accumulated metals within months."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0195$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Dredging records show how often a harbour was cleared. Sediment cores show layers of coarse material where dredging mixed the bed. Where the two records agree, historians can date a period of increased shipping. Where they disagree, one source is probably incomplete.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Disagreement proves both records are correct."},{"id":"B","text":"Agreement between independent records strengthens a claim about harbour use."},{"id":"C","text":"Dredging records and sediment cores always agree."},{"id":"D","text":"Coarse sediment indicates that no dredging occurred."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0196$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Cross-checking two independent records is what supports the dating.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The passage describes cases where they disagree.","D":"Mixed beds leave coarse layers.","A":"Disagreement is explained as incompleteness in one source."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0196$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$In permafrost, ice wedges form when meltwater enters cracks and refreezes. Repeated widening pushes the surrounding ground upward and outward, creating patterned polygons at the surface. Where the climate warms, wedges melt and the polygons subside. The pattern is therefore a visible record of ground temperature.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The patterns are unrelated to temperature."},{"id":"B","text":"Melting ice wedges raises the ground surface."},{"id":"C","text":"Changing polygon patterns can signal thawing permafrost."},{"id":"D","text":"Polygons form only where the ground never freezes."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0197$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The surface pattern tracks the state of the ice wedges.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Freezing meltwater is the mechanism.","B":"Melting causes subsidence.","A":"The passage links the pattern to ground temperature."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0197$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A fresco is painted on wet lime plaster. As the plaster sets, the pigment becomes part of the wall, which is why the color lasts. The painter must work quickly, because once the plaster dries the surface will not accept pigment in the same way. Frescoes were therefore planned in sections sized to one day's work.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"A painter could return to the same section weeks later."},{"id":"B","text":"The technique's durability depends on painting before the plaster sets."},{"id":"C","text":"Fresco pigment sits on top of dry plaster."},{"id":"D","text":"The sections were sized to the painter's arm length only."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0198$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The wet-plaster window explains both durability and the daily section plan.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The pigment becomes part of the wall as it sets.","A":"Dry plaster will not accept pigment the same way.","D":"Sections matched a day's work, not arm length."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0198$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A bridge cable is protected from rust by a galvanised coating that corrodes before the steel beneath. The coating is sacrificial: it gives up metal so the cable does not. Once the coating is consumed, the steel begins to rust, so inspectors measure coating thickness rather than waiting for visible damage.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"Inspectors should ignore the coating and wait for rust."},{"id":"B","text":"Measuring the protective layer gives earlier warning than looking for rust."},{"id":"C","text":"Galvanising makes steel immune to corrosion."},{"id":"D","text":"The coating outlasts the steel it protects."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0199$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Coating thickness is an early indicator of remaining protection.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"The coating corrodes so the steel does not.","A":"By the time rust shows, the coating is gone.","D":"Once consumed, the steel begins to rust."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0199$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A fish's otolith grows in annual rings, much like a tree. The rings record the temperature and chemistry of the water the fish inhabited, and a single otolith carries the whole life history of one animal. Researchers can therefore place a fish in particular waters at particular ages, even after it has been caught far away.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"An otolith changes after the fish dies, erasing its history."},{"id":"B","text":"Otoliths preserve a dated record of the environments."},{"id":"C","text":"Otoliths grow without annual layers."},{"id":"D","text":"Otolith rings record only the fish's age, not its environment."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0200$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Annual layers with environmental chemistry allow life-history reconstruction.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"The rings record water chemistry as well as age.","A":"The record survives in the recovered ear stone.","C":"The passage describes annual rings."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0200$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$In stony deserts, stones sometimes sit on pedestals of fine soil. Wind removes the loose material around a stone but cannot lift the stone itself, so the ground beneath it erodes more slowly. Over time the stone appears to rise. The pedestal is therefore a record of wind erosion, not of the stone being pushed upward.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"The stone is gradually lifted by rising air currents."},{"id":"B","text":"Pedestals form only where the ground is fully protected from wind."},{"id":"C","text":"The surrounding ground has been lowered, leaving the stone elevated."},{"id":"D","text":"Wind deposits soil beneath the stone."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0201$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Wind removes the surrounding soil faster than the protected ground beneath the stone, so the stone appears to rise.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Deflation removes material around the stone.","D":"The pedestal remains because erosion is slower beneath the stone.","B":"Wind erosion is the mechanism, not protection."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0201$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Many mushrooms fruit after rain, but rain alone is not enough. The mycelium must already have stored enough nutrients, and the air must cool enough to trigger development. A dry summer followed by a single storm often produces no flush, while a wet autumn with mild nights produces a large one.

______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"A single storm is sufficient to produce a mushroom flush."},{"id":"B","text":"Mycelium stores no nutrients before fruiting."},{"id":"C","text":"Mushrooms fruit best in dry, warm conditions."},{"id":"D","text":"Fruiting depends on accumulated reserves and temperature as well as moisture."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M10P-0202$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The passage identifies stored nutrients, cool nights and moisture as joint requirements, so no single storm is sufficient.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage says rain alone is not enough.","C":"Cooling nights and wet weather favor fruiting.","B":"Reserves are described as necessary."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M10P-0202$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Moths of one species rest on tree bark and range from pale to dark. In a forest where soot darkened the trunks, dark moths became more common over several decades. When air-quality rules later lightened the trunks, pale moths increased again. These shifts suggest that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"individual moths changed color as the bark darkened."},{"id":"B","text":"soot helped the moths find food more easily."},{"id":"C","text":"the species split into two separate populations."},{"id":"D","text":"Moths were more likely to be caught by birds."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-057$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The population shifts track how well each color matches the bark, which points to visual predators selecting the conspicuous moths. The other options require mechanisms the passage does not support.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"An individual moth cannot change its inherited color as bark darkens.","B":"The passage is about camouflage, not food finding.","C":"No splitting of the species is described."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-057$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$In a greenhouse, seedlings planted in soil from an old meadow grew larger than seedlings in soil from a young lawn, even though both soils had the same nutrients and water. When the meadow soil was heated to kill microbes, its advantage disappeared. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"meadow plants grow faster than lawn plants in every soil."},{"id":"B","text":"microorganisms in the meadow soil contributed to the seedlings' greater growth."},{"id":"C","text":"lawn soil cannot support seedlings under any conditions."},{"id":"D","text":"heating the soil added nutrients that the lawn soil lacked."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-058$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Because nutrients and water were equal, and killing microbes removed the advantage, the living organisms in the meadow soil are the remaining explanation.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"D":"Heating removed the advantage rather than creating one.","C":"Lawn soil supported seedlings; they simply grew less.","A":"The comparison is between soils, not between plant types."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-058$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Chemical residue inside cooking pots from a coastal settlement contained fats from both land animals and fish. The pots were found in households of similar size and age. This pattern suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"the settlement had no access to land animals."},{"id":"B","text":"fish were traded inland from the settlement."},{"id":"C","text":"the pots were used only for storage."},{"id":"D","text":"the households used a mix of land and marine foods rather than specializing in one."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-059$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$D$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$D$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Pots in comparable households held both kinds of fat, which points to mixed use rather than specialization. The other choices contradict the residue or add unsupported claims.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"Land-animal fats were found, so the settlement did have access to them.","B":"Trade is not mentioned in the passage.","C":"The pots were used for cooking, as the residue shows."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-059$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Young birds of one species raised in isolation develop songs that lack the local dialect heard in the wild. When recordings of the dialect are played to them during a sensitive period, their songs come to match it. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"isolation improves the accuracy of a bird's song."},{"id":"B","text":"young birds learn dialect features from what they hear rather than from instinct alone."},{"id":"C","text":"dialects are inherited genetically from parents."},{"id":"D","text":"adult birds can no longer learn new songs."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-060$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Isolated birds lacked the dialect, and hearing recordings restored it, which shows a learned component. That rules out a purely genetic explanation.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"Inherited song would not depend on hearing recordings.","D":"The study concerns young birds, not adult learning.","A":"Isolated songs lacked the local dialect."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-060$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A northern community builds a road across a frozen lake each winter. Officials close the road when measured ice thickness falls below a set level, even if the surface looks solid. This policy assumes that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"drivers can judge ice thickness reliably by looking at it."},{"id":"B","text":"Visible surface conditions can hide ice too thin."},{"id":"C","text":"thick ice never melts during the winter."},{"id":"D","text":"the road is used only during daylight hours."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-061$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Closing the road despite a solid-looking surface implies that appearance is not a safe guide. That is the assumption behind measuring thickness.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"No claim is made that ice never melts.","A":"The policy exists precisely because looking is not enough.","D":"The timing of use is not mentioned."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-061$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Gardeners in a neighborhood with older housing tested their soil and found elevated lead near building foundations. They moved vegetable beds away from the walls and added clean compost. Subsequent tests showed lower lead in the beds. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"compost removes lead from the vegetables that grow in it."},{"id":"B","text":"the first tests were performed incorrectly."},{"id":"C","text":"the beds' location and added soil, rather than the neighborhood as a whole, explained the earlier readings."},{"id":"D","text":"lead occurs naturally throughout the neighborhood's soil."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-062$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Lead was elevated only near foundations, and moving the beds plus adding clean soil lowered the readings, which points to local conditions rather than a neighborhood-wide problem.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The passage does not claim compost removes lead from plants.","D":"The pattern near foundations suggests a local source, not a uniform natural level.","B":"The change after relocating the beds supports the original tests rather than discrediting them."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-062$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Documents stored in a damp basement faded more than identical documents stored in a dry room. The ink in both sets was made from the same recipe. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"moisture accelerated the fading of the ink."},{"id":"B","text":"the basement documents were much older."},{"id":"C","text":"the ink recipe changed between the two sets."},{"id":"D","text":"light alone caused all of the fading."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-063$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The documents and ink were the same, so the storage condition is the difference that explains the extra fading. Moisture is the only variable named.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"Nothing indicates an age difference.","C":"The passage says both sets used the same recipe.","D":"Light conditions are not described as differing."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-063$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Lichen species differ in how much air pollution they tolerate. Surveys along a road found only tolerant species near the highway and a mix of tolerant and sensitive species farther away. This pattern suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"tolerant species require polluted air to survive."},{"id":"B","text":"pollution levels decline with distance from the highway."},{"id":"C","text":"sensitive species prefer the soil beside roads."},{"id":"D","text":"lichens move quickly from one site to another."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-064$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Sensitive lichens appear only where pollution is lower, which implies a gradient away from the road. That is the inference the survey supports.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"C":"Sensitive species were absent near the road, the opposite of preferring it.","A":"Tolerance does not mean a requirement for pollution.","D":"Dispersal speed is not discussed."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-064$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$A shoreline behind an oyster reef eroded less than a nearby shoreline without one. Waves reaching the first shore were measured as smaller. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"the reef reduced wave energy before the waves reached the shore."},{"id":"B","text":"oysters cement loose sand into solid rock."},{"id":"C","text":"the second shoreline had softer soil."},{"id":"D","text":"erosion depends only on the height of the tide."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-065$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$A$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$A$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$Smaller waves arrived where the reef stood, and that shore eroded less, which points to the reef absorbing wave energy.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"B":"No cementing process is described.","C":"Soil differences are not mentioned.","D":"The comparison isolates the presence of the reef."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-065$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Bats of one species forage along unlit paths more than along paths lit all night. When lamps were fitted with shields that directed light downward, bat activity along those paths increased. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"bats avoid every kind of artificial light equally."},{"id":"B","text":"the bats changed their diet after the shields were added."},{"id":"C","text":"light spilling sideways, not light itself, discouraged the bats."},{"id":"D","text":"shields attracted more insects to the paths."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-066$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$C$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$C$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$The lamps still shone, but shielding the sideways spill restored activity, so the direction of the light mattered. That isolates spill rather than light in general.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"The shielded paths were still lit and the bats returned.","D":"Insect numbers are not measured in the passage.","B":"Diet is not discussed."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-066$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Pressed specimens of one wildflower, collected over a century at the same site and stored identically, show earlier flowering dates in recent decades. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"the collectors visited the site only in spring."},{"id":"B","text":"the plants have been flowering earlier than they did a century ago."},{"id":"C","text":"pressing the flowers altered the dates on the labels."},{"id":"D","text":"the species has stopped flowering at this site."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-067$hdsat_report_fix$;
UPDATE public.question_keys SET correct_answer = $hdsat_report_fix$B$hdsat_report_fix$, acceptable_answers = ARRAY[$hdsat_report_fix$B$hdsat_report_fix$]::TEXT[], explanation = $hdsat_report_fix$With the site and storage held constant, the shift in recorded dates points to a real change in flowering time. That is the inference the evidence supports.$hdsat_report_fix$, distractor_rationales = $hdsat_report_fix${"A":"A spring-only collector could not produce the range of dates described.","C":"Pressing does not change the collection date on a label.","D":"The specimens document flowering, which continues."}$hdsat_report_fix$::jsonb, updated_at = NOW() WHERE question_id = $hdsat_report_fix$RW-M13-INFO-067$hdsat_report_fix$;
UPDATE public.questions SET stimulus = $hdsat_report_fix$Seeds of a shrub germinate readily after being heated to temperatures reached in a brush fire but rarely without heat. In unburned plots seedlings are scarce; in recently burned plots they are abundant. This suggests that ______$hdsat_report_fix$, prompt = $hdsat_report_fix$Which choice most logically completes the text?$hdsat_report_fix$, choices = $hdsat_report_fix$[{"id":"A","text":"fire supplies all the nutrients the shrub needs."},{"id":"B","text":"the shrub requires deep shade to reproduce."},{"id":"C","text":"fire cues trigger germination in this species."},{"id":"D","text":"heat kills most of the shrub's seeds."}]$hdsat_report_fix$::jsonb, figure_metadata = NULL, skill = $hdsat_report_fix$Inferences$hdsat_report_fix$, domain = $hdsat_report_fix$Information and Ideas$hdsat_report_fix$, difficulty = $hdsat_report_fix$Hard$hdsat_report_fix$, format = $hdsat_report_fix$multiple_choice$hdsat_report_fix$, assessments = ARRAY[$hdsat_report_fix$SAT$hdsat_report_fix$, $hdsat_report_fix$PSAT/NMSQT$hdsat_report_fix$, $hdsat_report_fix$PSAT 10$hdsat_report_fix$, $hdsat_report_fix$PSAT 8/9$hdsat_report_fix$]::TEXT[], updated_at = NOW() WHERE id = $hdsat_report_fix$RW-M13-INFO-068$hdsat_report_fix$;
